# v103: „Honnan jöttek a rómaiak?” – ősi DNS (Antonio et al. 2019) és izotópok (Killgrove–Montgomery 2016) a népességkártyán
COL={'eu':'#5f8f4e','med':'#1f5fa8','ne':'#c8792b','af':'#7a4e9c','ot':'#9aa3ad'}
def bar(segs,tot):
    return '      <div class="aqtot origbar">'+''.join('<div class="aqb" style="width:%.2f%%;background:%s">%d</div>'%(100*n/tot,COL[k],n) for k,n in segs)+'</div>'
def build(l):
    H=l=='hu';T=lambda h,e:h if H else e
    sw=lambda k:'<span class="sw" style="background:%s"></span>'%COL[k]
    o=[]
    o.append('    <section class="card" id="origcard">')
    o.append('      <h2>'+T('Honnan jöttek a rómaiak?','Where did the Romans come from?')+'</h2>')
    o.append('      <p class="hint">'+T('A város népességének nagyságáról csak becslések vannak (lásd „Róma népessége”), az összetételéről viszont két természettudományos vizsgálat közvetlen adatot ad a Róma környéki temetők csontjaiból. Mindkettő kis mintán alapul, ezért az arányok nem vetíthetők rá a város egész lakosságára.','For the size of the city\'s population there are only estimates (see “The population of Rome”), but two scientific studies give direct data on its make-up from bones in cemeteries around Rome. Both rest on small samples, so the proportions cannot be projected onto the whole population of the city.')+'</p>')
    o.append('      <h4 class="aqh4">'+T('Ősi DNS: a 48 császárkori egyén rokonsága','Ancient DNA: the affinities of the 48 imperial-period individuals')+'</h4>')
    o.append(bar([('med',31),('ne',13),('af',2),('eu',2)],48))
    o.append('      <p class="hint aqleg">'+sw('med')+T(' 31 közép- és kelet-mediterrán (a mai dél- és közép-itáliai, görög, ciprusi, máltai népességhez hasonló) · ',' 31 central and eastern Mediterranean (similar to present-day southern and central Italian, Greek, Cypriot and Maltese populations) · ')+sw('ne')+T(' 13 közel-keleti, levantei · ',' 13 Near Eastern, Levantine · ')+sw('af')+T(' 2 részben észak-afrikai · ',' 2 partly North African · ')+sw('eu')+T(' 2 európai (ebbe a csoportba tartozik a vaskori egyének többsége)',' 2 European (the group to which most Iron Age individuals belong)')+'</p>')
    o.append('      <h4 class="aqh4">'+T('Előtte: a 11 vaskori és köztársaság kori egyén','Before: the 11 Iron Age and Republican individuals')+'</h4>')
    o.append(bar([('eu',8),('ot',3)],11))
    o.append('      <p class="hint aqleg">'+sw('eu')+T(' 8 európai · ',' 8 European · ')+sw('ot')+T(' 3 más csoportban',' 3 in other groups')+'</p>')
    o.append('      <div class="regwrap"><table class="regtab aniotab origtab">')
    o.append('        <thead><tr><th>'+T('Korszak','Period')+'</th><th>'+T('Egyén','Individuals')+'</th><th>'+T('Mit mutat a DNS','What the DNA shows')+'</th></tr></thead>')
    o.append('        <tbody>')
    R=[(T('Vaskor és köztársaság (Kr. e. 900–27)','Iron Age and Republic (900–27 BC)'),'11',T('8 egyén az európai csoportban. Három egyénnél távolabbi eredetű keveredés látszik: két latin lelőhelyről származónál közel-keleti, egy etruszknál észak-afrikai.','8 individuals in the European group. Three show distant admixture: Near Eastern in two from Latin sites, North African in one Etruscan.')),
       (T('Császárkor (Kr. e. 27 – Kr. u. 300)','Imperial period (27 BC – AD 300)'),'48',T('Az európai csoportban már csak 2 egyén van; kétharmad mediterrán, negyed közel-keleti. Két egyén 30–50%-ban észak-afrikai eredetűnek modellezhető.','Only 2 individuals remain in the European group; two-thirds are Mediterranean, a quarter Near Eastern. Two can be modelled with 30–50% North African ancestry.')),
       (T('Késő ókor (300–700)','Late Antiquity (300–700)'),'24',T('Nagyjából egyenlő arányban kelet-mediterrán, mediterrán és európai; a közel-keleti csoport erősen visszaszorul. A Crypta Balbi 7 egyénéből 5 európai.','Roughly equal shares of eastern Mediterranean, Mediterranean and European; the Near Eastern group shrinks sharply. Of the 7 individuals from the Crypta Balbi, 5 are European.')),
       (T('Középkor és kora újkor (700–1800)','Medieval and early modern (700–1800)'),'28',T('Az európai csoport tovább nő, a közel-keleti és a kelet-mediterrán eltűnik; az átlag a mai közép-itáliaiakhoz áll közel.','The European group grows further, the Near Eastern and eastern Mediterranean ones disappear; the average is close to present-day central Italians.'))]
    for a,b,c in R: o.append('          <tr><td>'+a+'</td><td>'+b+'</td><td>'+c+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('M. L. Antonio, Z. Gao, H. M. Moots és társai, „Ancient Rome: A genetic crossroads of Europe and the Mediterranean”, <i>Science</i> 366 (2019) 708–714: 127 genom Róma és környéke 29 lelőhelyéről. A késő ókorra és a középkorra a cikk nem közöl darabszámot.','M. L. Antonio, Z. Gao, H. M. Moots et al., “Ancient Rome: A genetic crossroads of Europe and the Mediterranean”, <i>Science</i> 366 (2019) 708–714: 127 genomes from 29 sites in and around Rome. For Late Antiquity and the Middle Ages the article gives no counts.')+'</p>')
    o.append('      <p class="hint">'+T('A szerzők ebből arra következtetnek, hogy a császárkori Rómába jóval több ember érkezett a Földközi-tenger keleti feléből, mint a nyugati provinciákból. Az okot csak lehetőségként említik: a keleti országrész sűrűbben lakott volt, nagyvárosokkal. A portusi Isola Sacra temető kilenc egyéne közül négy a közel-keleti, négy a kelet-mediterrán, egy az európai csoportba tartozik, miközben oxigénizotópjaik szerint helyben nőhettek fel: ez tartósan letelepedett, vegyes eredetű közösségre utal. A csoportok statisztikai hasonlóságot jelentenek, nem népnevet; a szerzők maguk írják, hogy a forrásnépességeket nem szabad szó szerint érteni.','From this the authors conclude that many more people came to imperial Rome from the eastern half of the Mediterranean than from the western provinces. They mention the cause only as a possibility: the eastern part of the empire was more densely populated, with large cities. Of the nine individuals from the Isola Sacra cemetery at Portus, four belong to the Near Eastern, four to the eastern Mediterranean and one to the European group, while their oxygen isotopes are compatible with growing up locally: this points to a long-settled community of mixed origin. The groups express statistical similarity, not ethnic names; the authors themselves write that the source populations should not be taken literally.')+'</p>')
    o.append('      <h4 class="aqh4">'+T('Izotópok: ki nőtt fel máshol?','Isotopes: who grew up elsewhere?')+'</h4>')
    o.append('      <p class="hint">'+T('A fogzománc stroncium- és oxigénizotópjai a gyerekkori ivóvíz és táplálék nyomát őrzik. Akinek az értékei kilógnak a Róma környéki tartományból, az máshol töltötte a gyerekkorát. Két, Kr. u. 1–3. századi külvárosi temető 105 egyénét vizsgálták meg.','The strontium and oxygen isotopes of tooth enamel preserve the trace of childhood drinking water and food. Anyone whose values fall outside the range around Rome spent their childhood elsewhere. A total of 105 individuals from two suburban cemeteries of the 1st–3rd centuries AD were analysed.')+'</p>')
    o.append('      <div class="regwrap"><table class="regtab aniotab origtab">')
    o.append('        <thead><tr><th>'+T('Temető','Cemetery')+'</th><th>'+T('Vizsgált egyén','Individuals analysed')+'</th><th>'+T('Valószínűleg máshol nőtt fel','Probably grew up elsewhere')+'</th></tr></thead>')
    o.append('        <tbody>')
    R=[(T('Casal Bertone, mauzóleum (a Via Praenestinán, kb. 1,5 km-re az Aurelianus-faltól keletre)','Casal Bertone, mausoleum (on the Via Praenestina, about 1.5 km east of the Aurelian Wall)'),'22','0'),
       (T('Casal Bertone, egyszerű sírok (nekropolisz)','Casal Bertone, simple graves (necropolis)'),'57','3'),
       (T('Castellaccio Europarco (a Via Laurentinán, kb. 12 km-re délre)','Castellaccio Europarco (on the Via Laurentina, about 12 km to the south)'),'26','1'),
       (T('<b>Együtt</b>','<b>Total</b>'),'<b>105</b>','<b>4</b>')]
    for a,b,c in R: o.append('          <tr><td>'+a+'</td><td>'+b+'</td><td>'+c+'</td></tr>')
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('K. Killgrove, J. Montgomery, „All Roads Lead to Rome: Exploring Human Migration to the Eternal City through Biochemistry of Skeletons from Two Imperial-Era Cemeteries (1st–3rd c AD)”, <i>PLOS ONE</i> 11(2) (2016) e0147585, 1–2. táblázat és a szöveg (CC BY 4.0).','K. Killgrove, J. Montgomery, “All Roads Lead to Rome: Exploring Human Migration to the Eternal City through Biochemistry of Skeletons from Two Imperial-Era Cemeteries (1st–3rd c AD)”, <i>PLOS ONE</i> 11(2) (2016) e0147585, Tables 1–2 and text (CC BY 4.0).')+'</p>')
    o.append('      <p class="hint">'+T('A négy egyén három felnőtt férfi és egy 11–15 éves serdülő. Kettőjük stronciumértéke idősebb kőzetű vidékre utal, például az Alpokra vagy a Tirrén-tenger valamelyik szigetére; egyé hűvösebb, csapadékosabb tájra, például az Appenninekre; egyé melegebb, szárazabbra, például Észak-Afrikára. További négy egyén értékei is eltérnek, de ez statisztikailag nem bizonyító. A drágább mauzóleumban senki sem volt kimutathatóan idegen, az egyszerű sírokban igen.','The four individuals are three adult men and one adolescent aged 11–15. The strontium values of two point to a region of older rock, such as the Alps or one of the islands of the Tyrrhenian Sea; one to a cooler, wetter landscape such as the Apennines; one to a hotter, drier one such as North Africa. Four further individuals also deviate, but this is not statistically conclusive. In the more expensive mausoleum nobody was detectably foreign; in the simple graves some were.')+'</p>')
    o.append('      <p class="hint">'+T('A 105-ből 4 (3,8%) alsó határ, nem a bevándorlók aránya: aki Rómához hasonló kőzetű és éghajlatú vidékről jött, az a módszer számára láthatatlan, és a rabszolgák közül is sokan itt születtek. A két vizsgálat ezért nem mond ellent egymásnak: a DNS a több nemzedékkel korábbi eredetet is mutatja, az izotóp csak azt, hogy maga az egyén hol nőtt fel.','The 4 out of 105 (3.8%) is a lower bound, not the share of immigrants: anyone who came from a region with rock and climate similar to Rome\'s is invisible to the method, and many slaves were also born here. So the two studies do not contradict each other: DNA also shows origins several generations back, while isotopes show only where the individual grew up.')+'</p>')
    o.append('    </section>')
    return '\n'.join(o)+'\n'
SRCLI=lambda l:('      <li><b>A rómaiak eredete: ősi DNS és izotópok.</b> M. L. Antonio, Z. Gao, H. M. Moots és társai: Ancient Rome: A genetic crossroads of Europe and the Mediterranean, <i>Science</i> 366 (2019) 708–714 (a darabszámok a cikk szövegéből; saját összefoglalás). K. Killgrove, J. Montgomery: All Roads Lead to Rome, <i>PLOS ONE</i> 11(2) (2016) e0147585 (CC BY 4.0): a 105 egyén mérési adatai az 1–2. táblázatból, a négy nem helyi egyén a szerzők statisztikai próbája szerint.</li>' if l=='hu' else '      <li><b>The origins of the Romans: ancient DNA and isotopes.</b> M. L. Antonio, Z. Gao, H. M. Moots et al.: Ancient Rome: A genetic crossroads of Europe and the Mediterranean, <i>Science</i> 366 (2019) 708–714 (counts from the text of the article; own summary). K. Killgrove, J. Montgomery: All Roads Lead to Rome, <i>PLOS ONE</i> 11(2) (2016) e0147585 (CC BY 4.0): measurements of the 105 individuals from Tables 1–2, the four non-local individuals according to the authors\' statistical test.</li>')

SUB=('ősi DNS 127 genomból és 105 csontváz izotópjai: eredet és bevándorlás','ancient DNA from 127 genomes and the isotopes of 105 skeletons: origins and immigration')
